import React, { useMemo, useState } from 'react'
import styles from './styles.module.css'

// Generated by scripts/generate-props.mjs from the component's propTypes and defaultProps.
const propsContext = require.context('@site/src/data/props', false, /\.json$/)

function loadComponent(component) {
  const key = `./${component}.json`
  return propsContext.keys().includes(key) ? propsContext(key) : null
}

function Type({ prop }) {
  if (!prop.fields) return <code>{prop.text}</code>
  return (
    <details className={styles.shape}>
      <summary>
        <code>object</code> <span className={styles.muted}>({prop.fields.length} fields)</span>
      </summary>
      <ul>
        {prop.fields.map((field) => (
          <li key={field.name}>
            <code>
              {field.name}
              {field.required ? '' : '?'}: {field.type}
            </code>
          </li>
        ))}
      </ul>
    </details>
  )
}

export default function PropsTable({ component }) {
  const data = loadComponent(component)
  const [query, setQuery] = useState('')
  const props = useMemo(() => (data ? data.props.filter((p) => !p.internal) : []), [data])
  const shown = useMemo(() => {
    const q = query.trim().toLowerCase()
    if (!q) return props
    return props.filter((p) => p.name.toLowerCase().includes(q) || p.description.toLowerCase().includes(q))
  }, [props, query])

  if (!data) {
    return (
      <p className={styles.muted}>
        No prop data for {component}. Run <code>npm run props</code> in <code>docs/</code>.
      </p>
    )
  }

  return (
    <div className={styles.wrap}>
      <div className={styles.toolbar}>
        <input
          className={styles.search}
          type='search'
          placeholder={`Filter ${props.length} props`}
          aria-label={`Filter ${component} props`}
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
        <span className={styles.muted}>
          Generated from <code>{data.file}</code>
        </span>
      </div>
      <div className={styles.scroller}>
        <table className={styles.table}>
          <thead>
            <tr>
              <th>Prop</th>
              <th>Type</th>
              <th>Default</th>
              <th>Description</th>
            </tr>
          </thead>
          <tbody>
            {shown.map((prop) => (
              <tr key={prop.name} id={`prop-${prop.name}`}>
                <td>
                  <code className={styles.name}>{prop.name}</code>
                  {prop.required && <span className={styles.required}>required</span>}
                </td>
                <td>
                  <Type prop={prop} />
                </td>
                <td>
                  {prop.default != null ? (
                    <code>{prop.default}</code>
                  ) : (
                    <span className={styles.muted}>{prop.defaultNote || '–'}</span>
                  )}
                </td>
                <td>{prop.description || <span className={styles.muted}>No description yet.</span>}</td>
              </tr>
            ))}
            {!shown.length && (
              <tr>
                <td colSpan={4} className={styles.muted}>
                  No props match "{query}".
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  )
}
